  2790          for (i = 0; i < d->m_fmt; ++i) d->fmt[i].p_free = 0;
  2791          for (i = 0; i < b->n_fmt; ++i)
  2792              ptr = bcf_unpack_fmt_core1(ptr, b->n_sample, &d->fmt[i]);
  2793          b->unpacked |= BCF_UN_FMT;
