    84      if (!in) {
    85          return;
    86      }
    87      vcfFile *out = vcf_open("/dev/null", "w");
    88      if (!out) {
    89          abort();
    90      }
    91      bcf_hdr_t *hdr = bcf_hdr_read(in);
    92      if (hdr == NULL) {
    93          hts_close_or_abort(out);
    94          return;
    95      }
    96
    97      if (bcf_hdr_write(out, hdr) != 0) {
    98          bcf_hdr_destroy(hdr);
    99          hts_close_or_abort(out);
   100      }
   101      bcf1_t *rec = bcf_init();
   102      if (rec == NULL) {
   103          bcf_hdr_destroy(hdr);
   104          hts_close_or_abort(out);
   105      }
   106      while (bcf_read(in, hdr, rec) >= 0) {
